import unittest
from xml.dom import minidom

from ta_emss.utilities.SCFC_parser_lib.scfc_elements.Managed_Object import ManagedObject


class TestManagedObject(unittest.TestCase):
    def setUp(self):
        managed_objects = minidom.parse("/home/ute/Desktop/Add_cell_2.xml").getElementsByTagName('managedObject')
        self.lnbts = ManagedObject(managed_objects[0])
        self.lncel = ManagedObject(managed_objects[-1])
        self.topf = ManagedObject(managed_objects[-2])

    def test_get_object_path(self):
        self.assertEqual(self.lnbts.get_object_path(), "MRBTS-88/LNBTS-88")

